mapper.select:
WITH U AS( SELECT DENSE_RANK() OVER(ORDER BY T.DOC_NO DESC) RNUM , T.*, D.DEPT_NM, D.DEPT_NO FROM ( SELECT DOC_NO, A.USER_NO, DOC_TITLE, DOC_CONTENT, DOC_CREATE_DATE, DOC_TYPE_NO , (SELECT B.USER_NM FROM TB_USER B WHERE B.USER_NO = A.USER_NO) USER_NM , (select dt.doc_type_nm from doc_type dt where dt.doc_type_no = A.doc_type_no) doc_type_nm , A.FILE_GROUP_NO, A.FILE_SAVE_LOCATE, A.FILE_ORIGINAL_NAME FROM ( SELECT * FROM SANCTION_DOC X LEFT OUTER JOIN FILE_GROUP Y ON(X.FILE_GROUP_NO = Y.FILE_GROUP_NO) LEFT OUTER JOIN FILE_DETAIL Z ON(Y.FILE_GROUP_NO = Z.FILE_GROUP_NO) ) A
) T, EMPLOYEE E, DEPT D WHERE T.USER_NO = E.USER_NO AND E.DEPT_NO = D.DEPT_NO
) SELECT * FROM U WHERE U.RNUM BETWEEN (#{currentPage} * 10) - (10-1) AND (#{currentPage} * 10)

WITH U AS( SELECT DENSE_RANK() OVER(ORDER BY T.DOC_NO DESC) RNUM , T.* FROM ( SELECT SD.DOC_NO, SD.DOC_TITLE, DT.DOC_TYPE_NM, SD.DOC_CREATE_DATE, TU.USER_NM AS SANCTION_USER_NM, S.SANCTION_DATE, SANCTION_STATUS_NM, ROW_NUMBER() OVER ( PARTITION BY SD.DOC_NO ORDER BY CASE WHEN S.SANCTION_STATUS_NO = 3 THEN 1 WHEN S.SANCTION_STATUS_NO = 1 THEN 2 WHEN S.SANCTION_STATUS_NO = 2 THEN 3 END ) AS RANKING FROM SANCTION S JOIN TB_USER TU ON S.SANCTION_USER = TU.USER_NO JOIN SANCTION_STATUS SS ON S.SANCTION_STATUS_NO = SS.SANCTION_STATUS_NO JOIN SANCTION_DOC SD ON S.DOC_NO = SD.DOC_NO JOIN DOC_TYPE DT ON SD.DOC_TYPE_NO = DT.DOC_TYPE_NO
WHERE SD.USER_NO = #{userId}
) T WHERE RANKING = 1 AND (T.SANCTION_STATUS_NM LIKE '%' || #{keyword} || '%' OR T.DOC_TITLE LIKE '%' || #{keyword} || '%' ) ) SELECT * FROM U WHERE U.RNUM BETWEEN (#{currentPage} * 10) - (10-1) AND (#{currentPage} * 10)

WITH U AS( SELECT DENSE_RANK() OVER(ORDER BY T.DOC_NO DESC) RNUM , T.*, D.DEPT_NM, D.DEPT_NO FROM ( SELECT DOC_NO, A.USER_NO, DOC_TITLE, DOC_CONTENT, DOC_CREATE_DATE, DOC_TYPE_NO , (SELECT B.USER_NM FROM TB_USER B WHERE B.USER_NO = A.USER_NO) USER_NM , A.FILE_GROUP_NO, A.FILE_SAVE_LOCATE, A.FILE_ORIGINAL_NAME FROM ( SELECT * FROM SANCTION_DOC X LEFT OUTER JOIN FILE_GROUP Y ON(X.FILE_GROUP_NO = Y.FILE_GROUP_NO) LEFT OUTER JOIN FILE_DETAIL Z ON(Y.FILE_GROUP_NO = Z.FILE_GROUP_NO) ) A WHERE DOC_TYPE_NO = '4'
) T, EMPLOYEE E, DEPT D WHERE T.USER_NO = E.USER_NO AND E.DEPT_NO = D.DEPT_NO
) SELECT * FROM U WHERE U.RNUM BETWEEN (#{currentPage} * 10) - (10-1) AND (#{currentPage} * 10)

