	UPDATE SANCTION
	SET SANCTION_STATUS_NO = 2
		,SANCTION_DATE = SYSDATE
	WHERE DOC_NO = #{docNo}
    AND SANCTION_USER = #{sanctionUser}

	UPDATE SANCTION
	SET SANCTION_STATUS_NO = 3
		,SANCTION_DATE = SYSDATE
	WHERE DOC_NO = #{docNo}
    AND SANCTION_USER = #{sanctionUser}

UPDATE SANCTION_DOC
SET DOC_REJECT = #{docReject}	
WHERE DOC_NO = #{docNo}

